insert into ob_pages (key, kind, dept_slug, title, title_th, eyebrow, eyebrow_th, lead, lead_th, note, note_th, hero_image, closing, sort_order) values ('home', 'home', null, 'VCB 90-Day Onboarding Portal', 'พอร์ทัลปฐมนิเทศพนักงานใหม่ 90 วัน VCB', null, null, 'This portal defines the required knowledge, system mastery, execution standards, and governance expectations for all new employees during their first 90 days.', 'พอร์ทัลนี้กำหนดความรู้ที่จำเป็น ความเชี่ยวชาญในระบบ มาตรฐานการปฏิบัติงาน และข้อกำหนดด้านธรรมาภิบาลสำหรับพนักงานใหม่ทุกคนในช่วง 90 วันแรก', 'Confirmation of employment is based on competency, documentation accuracy, system discipline, and risk awareness.', 'การยืนยันการจ้างงานพิจารณาจากความสามารถ ความถูกต้องของเอกสาร วินัยในการใช้ระบบ และความตระหนักถึงความเสี่ยง', 'homeHeroPhoto', '{"label":"Continue to Required Documents","page":"required-documents"}'::jsonb, 1) on conflict (key) do update set kind = excluded.kind, dept_slug = excluded.dept_slug, title = excluded.title, title_th = excluded.title_th, eyebrow = excluded.eyebrow, eyebrow_th = excluded.eyebrow_th, lead = excluded.lead, lead_th = excluded.lead_th, note = excluded.note, note_th = excluded.note_th, hero_image = excluded.hero_image, closing = excluded.closing, sort_order = excluded.sort_order, is_active = true;
