delete from ob_sections where page_key in ('home', 'required-documents', 'accounting-team', 'finance-team', 'procurement-team', 'property-asset-management', 'engineering-team', 'meet-our-team', 'life-on-site', 'completion');
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('home', 'main', 1, 'quote', null, 'light', 'Welcome Message from our CEO', 'สารต้อนรับจากท่านกรรมการผู้จัดการ', null, null, '{"quote":"We’re thrilled to have you onboard. We believe that every person here contributes to our success, and we’re committed to helping you thrive. Let’s build something great together.","quote_th":"เรารู้สึกยินดีเป็นอย่างยิ่งที่คุณมาร่วมงานกับเรา เราเชื่อว่าทุกคนที่นี่มีส่วนร่วมต่อความสำเร็จของเรา และเรามุ่งมั่นที่จะช่วยให้คุณเติบโตก้าวหน้า มาร่วมกันสร้างสิ่งที่ยิ่งใหญ่ไปด้วยกัน","attribution":"Mr. Voravith Chavananand","attribution_th":"นาย วรวิทย์ ชวนะนันท์","portrait":{"imageKey":"ceoPortrait"}}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('home', 'main', 2, 'values', null, 'teal', 'VCB Culture & Values', 'วัฒนธรรมและค่านิยมของ VCB', 'What we stand for — internalize these from Day 0', 'สิ่งที่เรายึดถือ — โปรดซึมซับตั้งแต่วันแรก', '{"values":[{"name":"Discipline","name_th":"วินัย","icon":{"imageKey":"valueIconDiscipline"},"body":"We follow structured systems, documented processes, and approval hierarchies.","body_th":"เราปฏิบัติตามระบบที่มีโครงสร้าง กระบวนการที่มีการบันทึกเป็นเอกสาร และลำดับขั้นการอนุมัติ","bullets":["No shortcuts","No undocumented commitments","No uncontrolled decisions"],"bullets_th":["ไม่มีทางลัด","ไม่มีข้อผูกพันที่ไม่มีเอกสารรองรับ","ไม่มีการตัดสินใจที่ไม่มีการควบคุม"],"footer":"Discipline protects our liquidity, reputation, and long-term stability.","footer_th":"วินัยช่วยปกป้องสภาพคล่อง ชื่อเสียง และความมั่นคงในระยะยาวของเรา"},{"name":"Responsibility","name_th":"ความรับผิดชอบ","icon":{"imageKey":"valueIconAccountability"},"body":"Every action has operational and financial impact. We take ownership of:","body_th":"ทุกการกระทำส่งผลกระทบต่อการดำเนินงานและการเงิน เรารับผิดชอบต่อ:","bullets":["Our decisions","Our documentation","Our deadlines","Our results"],"bullets_th":["การตัดสินใจของเรา","เอกสารของเรา","กำหนดเวลาของเรา","ผลลัพธ์ของเรา"],"footer":"Responsibility is not transferred — it is upheld.","footer_th":"ความรับผิดชอบไม่ใช่สิ่งที่โอนต่อได้ — แต่ต้องยึดมั่นไว้"},{"name":"Integrity","name_th":"ความซื่อสัตย์","icon":{"imageKey":"valueIconIntegrity"},"body":"We operate with transparency, honesty, and regulatory compliance.","body_th":"เราดำเนินงานด้วยความโปร่งใส ความซื่อสัตย์ และการปฏิบัติตามกฎระเบียบ","bullets":["Accurate reporting","Honest measurement","Proper documentation","Respect for public trust"],"bullets_th":["การรายงานที่ถูกต้อง","การวัดผลอย่างตรงไปตรงมา","เอกสารที่ถูกต้องครบถ้วน","การเคารพความไว้วางใจของสาธารณะ"],"footer":"Integrity ensures sustainability.","footer_th":"ความซื่อสัตย์คือหลักประกันความยั่งยืน"},{"name":"Excellence","name_th":"ความประณีต","icon":{"imageKey":"valueIconExcellence"},"body":"We execute with precision, coordination, and continuous improvement.","body_th":"เราทำงานด้วยความแม่นยำ การประสานงาน และการพัฒนาอย่างต่อเนื่อง","bullets":["Accurate quantities","Controlled costs","Timely delivery","Risk awareness"],"bullets_th":["ปริมาณงานที่ถูกต้อง","ต้นทุนที่ควบคุมได้","ส่งมอบงานตรงเวลา","ความตระหนักถึงความเสี่ยง"],"footer":"Excellence is achieved through consistency, not chance.","footer_th":"ความเป็นเลิศเกิดจากความสม่ำเสมอ ไม่ใช่ความบังเอิญ"}]}'::jsonb);
