insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('home', 'main', 4, 'orgchart', null, 'teal', 'Company Structure', null, null, null, '{"chartSubheading":"Click Leadership or any team to see who’s in it, then click someone to see what they do.","groupSubheading":"Vichitbhan’s position relative to its subsidiaries and joint-venture partners.","leadership":{"id":"leadership","label":"Leadership","levels":[{"heading":"Board of Directors","members":[{"name":"Mr. Somchai Placeholder","role":"Director"},{"name":"Mr. Anurak Placeholder","role":"Director"},{"name":"Mr. Kittipong Placeholder","role":"Director"},{"name":"Mrs. Suchada Placeholder","role":"Director"}]},{"heading":"Board Advisors","members":[{"name":"Mr. Prasert Placeholder","role":"Advisor to the Board"},{"name":"Mr. Somkiat Placeholder","role":"Advisor to the Board"}]},{"heading":"Managing Director","heading_th":"กรรมการผู้จัดการ","members":[{"name":"Mr. Somchai Placeholder","role":"Managing Director — sets company direction and owns the final call on every major decision."}]},{"heading":"Assistant Managing Directors","members":[{"name":"Mr. Kittipong Placeholder","role":"Assistant Managing Director — oversees day-to-day operations across all departments."},{"name":"Mr. Narong Placeholder","role":"Assistant Managing Director — leads strategic planning and cross-department coordination."}]}]},"departments":[{"id":"engineering","label":"Engineering Team","label_th":"ทีมวิศวกรรม","members":[{"name":"Mr. Thanawat Placeholder","role":"Head of Engineering — owns execution accuracy and revenue realization."},{"name":"Mr. Pichai Placeholder","role":"Reviews site progress against approved drawings and specifications."},{"name":"Mrs. Malee Placeholder","role":"Senior Engineer Officer — coordinates measurement and progress documentation."},{"name":"Mr. Somsak Placeholder","role":"Tracks material and labor efficiency across active sites."},{"name":"Mr. Wichai Placeholder","role":"Prepares documentation supporting progress claims."},{"name":"Mrs. Ratana Placeholder","role":"Coordinates schedules between Engineering and Project Management."}]},{"id":"accounting","label":"Accounting Team","label_th":"ทีมบัญชี","members":[{"name":"Mrs. Pranee Placeholder","role":"Head of Accounting — owns documentation discipline and audit readiness."},{"name":"Mrs. Siriporn Placeholder","role":"Accounting Assistant — supports new employee onboarding and daily postings."},{"name":"Ms. Kanya Placeholder","role":"Handles AP/AR posting and invoice verification."},{"name":"Ms. Orapin Placeholder","role":"Manages VAT and withholding tax reconciliation."},{"name":"Ms. Duangjai Placeholder","role":"Maintains the Chart of Accounts and journal entry accuracy."},{"name":"Ms. Nittaya Placeholder","role":"Prepares monthly reconciliation reports."}]},{"id":"finance","label":"Finance Team","label_th":"ทีมการเงิน","members":[{"name":"Mr. Chatchai Placeholder","role":"Head of Finance — safeguards liquidity and long-term financial stability."},{"name":"Mrs. Sunisa Placeholder","role":"Senior Finance Officer — monitors cashflow and funding requirements."},{"name":"Ms. Waraporn Placeholder","role":"Manages banking facilities and financing instruments."},{"name":"Mr. Anucha Placeholder","role":"Tracks debt servicing capacity and liquidity exposure."}]},{"id":"asset","label":"Asset Management","label_th":"บริหารทรัพย์สิน","branches":[{"id":"asset-inventory","label":"Inventory & Land","members":[{"name":"Mr. Prayut Placeholder","role":"Head of Asset Management — protects company-owned assets and inventory integrity."},{"name":"Mr. Somboon Placeholder","role":"Conducts periodic physical verification of site equipment."},{"name":"Ms. Ampha Placeholder","role":"Maintains asset registration and warehouse movement records for inventory, land, and non-vehicle assets."}]},{"id":"asset-sai5","label":"Vehicles & Machinery","offsite":true,"loca