ting / Shop Drawing","lead":{"name":"Mr. Somjit Placeholder","role":"Design & Budgeting Engineer"},"staff":[{"name":"Mr. Kittisak Placeholder","role":"Quantity Surveyor"},{"name":"Mr. Anucha Placeholder","role":"Draftsman"}]},{"label":"Survey","lead":{"name":"Mr. Preecha Placeholder","role":"Survey Engineer"},"staff":[{"name":"Mr. Somsak Placeholder","role":"Survey Technician"},{"name":"Mr. Wichai Placeholder","role":"Survey Technician"}]},{"label":"Structural & Bridge Works","lead":{"name":"Mr. Amnat Placeholder","role":"Construction Supervisor Engineer"},"staff":[{"name":"Mr. Direk Placeholder","role":"Foreman"},{"name":"Mr. Boonchu Placeholder","role":"Foreman"}]},{"label":"Roadworks / Drainage Systems","lead":{"name":"Mr. Kamon Placeholder","role":"Construction Supervisor Engineer"},"staff":[{"name":"Mr. Ratana Placeholder","role":"Foreman"},{"name":"Mr. Sompong Placeholder","role":"Equipment Operator"}]},{"label":"Safety / Traffic Control","lead":{"name":"Mr. Winai Placeholder","role":"Professional Safety Officer"},"staff":[{"name":"Mr. Ekachai Placeholder","role":"Traffic Control Officer"},{"name":"Mr. Pravit Placeholder","role":"Traffic Control Officer"}]}],"adminDepartments":[{"label":"Maintenance","lead":{"name":"Mr. Suriya Placeholder","role":"Maintenance Supervisor"},"hqDept":"asset","staff":[{"name":"Mr. Anan Placeholder","role":"Electrician"},{"name":"Mr. Sakda Placeholder","role":"Mechanic"}]},{"label":"Supplies & Asset Management","lead":{"name":"Mr. Thawee Placeholder","role":"Supplies & Asset Officer"},"hqDept":"asset","staff":[{"name":"Mr. Pichit Placeholder","role":"Store Officer"},{"name":"Mr. Charnwit Placeholder","role":"Store Officer"}]},{"label":"Accounting - Finance - Procurement","lead":{"name":"Ms. Areeya Placeholder","role":"Site Accounting & Procurement Officer"},"hqDept":"accounting","staff":[{"name":"Ms. Kanya Placeholder","role":"Accounting Officer"},{"name":"Ms. Duangjai Placeholder","role":"Procurement Officer"}]},{"label":"HR - Administration","lead":{"name":"Ms. Rungnapa Placeholder","role":"Site HR & Administration Officer"},"hqDept":"hr","staff":[{"name":"Ms. Siriporn Placeholder","role":"HR Officer"},{"name":"Ms. Malee Placeholder","role":"Admin Officer"}]}]}]},"groupStructure":{"groupName":"Vichitbhan Group","groupName_th":"กลุ่มบริษัทวิจิตรภัณฑ์","shareholders":[{"id":"chavananand","label":"Chavananand Family","label_th":"ตระกูลชวนะนันท์"}],"parent":{"id":"vcb","label":"Vichitbhan Construction Co., Ltd.","label_th":"บริษัท วิจิตรภัณฑ์ก่อสร้าง จำกัด","sub":"Vichitbhan Construction Company Limited (VCB) is a construction company specializing in large-scale infrastructure projects, including highways, roads, dams, and precast concrete works. The company primarily serves government and public-sector clients, delivering construction projects through its engineering, project management, procurement, and support functions.","sub_th":"บริษัท วิจิตรภัณฑ์ก่อสร้าง จำกัด (VCB) เป็นบริษัทรับเหมาก่อสร้างที่เชี่ยวชาญด้านโครงการโครงสร้างพื้นฐานขนาดใหญ่ ครอบคลุมงานทางหลวง ถนน เขื่อน และงานคอนกรีตสำเร็จรูป โดยให้บริการหลักแก่หน่วยงานภาครัฐและภาคสาธารณะ ผ่านการดำเนินงานด้านวิศวกรรม การบริหารโครงการ การจัดซื้อจัดจ้าง และฝ่ายสนับสนุนต่าง ๆ"},"familyCompanies":[{"id":"vpo","label":"Vichitbhan Palm Oil PCL (VPO)","label_th":"บริษัท วิจิตรภัณฑ์ปาล์มออยล์ จำกัด (มหาชน) (VPO)","sub":"Vichitbhan Palm Oil PCL is a Thailand-based company engaged in palm plantation and palm oil extraction. Its product line consists of crude palm oil, palm kernel, by-products such as shells, empty bunches, decanter cakes, and palm fiber products, and electricity which is produced from the treated waste water of the Palm Oil Crushing Mill.","sub_th":"บริษัท วิจิตรภัณฑ์ปาล์มออยล์ จำกัด (มหาชน) เป็นบริษัทสัญชาติไทยที่ดำเนินธุรกิจสวนปาล์มและการสกัดน้ำมันปาล์ม สายผลิตภัณฑ์ประกอบด้วยน้ำมันปาล์มดิบ เมล็ดในปาล์ม ผลพลอยได้ เช่น กะลา ทะลายเปล่า กากตะกอน และผลิตภัณฑ์เส้นใยปาล์ม รวมถึงกระแสไฟฟ้าที่ผลิตจากน้ำเสียที่ผ่านการบำบัดของโรงงานสกัดน้ำมันปาล์ม"},{"id":"chavananand-holding","label":"Chavananand Holding Co., Ltd.","label_th":"บริษัท ชวนะนันท์ โฮลดิ้ง จำกัด","sub":"Operates and manages a commercial building, overseeing its day-to-day operations, maintenance, and tenant services. The company also manages the leasing of office spaces within the building, including tenant relations and rental administration.","sub_th":"บริหารจัดการอาคารพาณิชย์ ดูแลการดำเนินงานประจำวัน การบำรุงรักษา และบริการผู้เช่า รวมถึงบริหารจัดการพื้นที่สำนักงานให้เช่าภายในอาคาร ครอบคลุมความสัมพันธ์กับผู้เช่าและการบริหารงานด้านการเช่า"}],"subsidiaries":[{"id":"cve","label":"CVE","sub":"Manufactures pre-cast concrete components for Vichitbhan Group’s construction projects.","sub_th":"ผลิตชิ้นส่วนคอนกรีตสำเร็จรูปเพื่อใช้ในโครงการก่อสร้างของกลุ่มบริษัทวิจิตรภัณฑ์"},{"id":"cvn","label":"CVN Development","sub":"Develops property ventures on behalf of Vichitbhan Group, currently being established."}],"jvs":[{"id":"vk","label":"VK","parents":["Vichitbhan Construction Co., Ltd.","Kolatach"]},{"id":"v-and-k","label":"V&K","parents":["Vichitbhan Construction Co., Ltd.","Kolatach"]},{"id":"vn","label":"VN","parents":["Vichitbhan Construction Co., Ltd.","Napa Construction"]},{"id":"vc","label":"VC","parents":["Vichitbhan Construction Co., Ltd.","CVN Development"]}]}}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('required-documents', 'main', 1, 'text', null, 'light', null, null, null, null, '{"body":["Your first working day will include an orientation session introducing the company, internal procedures, and your department."],"body_th":["วันแรกของการทำงานจะมีช่วงปฐมนิเทศเพื่อแนะนำบริษัท ขั้นตอนการทำงานภายใน และแผนกของคุณ"],"link":{"label":"View Orientation Schedule","label_th":"ดูตารางปฐมนิเทศ","url":"https://drive.google.com/uc?export=download&id=1ORoLccHOZCcIijLQIMvfmSys0En2Y3Q7"}}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('required-documents', 'main', 2, 'deptgrid', 'department-selection', 'teal', 'Department Selection', 'เลือกแผนก', null, null, '{"eyebrow":"The most important step in pre-boarding","eyebrow_th":"ขั้นตอนที่สำคัญที่สุดในการเตรียมความพร้อมก่อนเริ่มงาน","intro":"Choose the department you will spend your first 90 days in. This sets the checklists, milestones, and people you’ll work with from here on — choose carefully.","intro_th":"เลือกแผนกที่คุณจะใช้เวลา 90 วันแรกด้วย การเลือกนี้จะกำหนดรายการตรวจสอบ เป้าหมาย และผู้ร่วมงานของคุณตั้งแต่นี้ไป — กรุณาเลือกอย่างรอบคอบ","depts":[{"deptId":"accounting","label":"Accounting Team","label_th":"ทีมบัญชี","page":"accounting-team","icon":"ledger","desc":"Keep the company’s financial records complete, transparent, and audit-ready.","desc_th":"ดูแลบันทึกทางการเงินของบริษัทให้ครบถ้วน โปร่งใส และพร้อมสำหรับการตรวจสอบ","lead":"Mrs. Wanpen Yamploy, Head of Accounting","focus":"Recording, tax compliance, audit readiness"},{"deptId":"finance","label":"Finance Team","label_th":"ทีมการเงิน","page":"finance-team","icon":"coin","desc":"Protect liquidity and long-term financial stability through controlled cashflow.","desc_th":"ปกป้องสภาพคล่องและความมั่นคงทางการเงินในระยะยาวผ่านการควบคุมกระแสเงินสด","lead":"Mr. Vivich Chavananand, Head of Finance","focus":"Cashflow, financing, debt management"},{"deptId":"procurement","label":"Procurement Team","label_th":"ทีมจัดซื้อ","page":"procurement-team","icon":"package","desc":"Secure materials and services on terms that protect cost, schedule, and quality.","desc_th":"จัดหาวัสดุและบริการภายใต้เงื่อนไขที่ปกป้องต้นทุน กำหนดเวลา และคุณภาพ","lead":"Mrs. Thongthip Chavananand, Head of Procurement","focus":"Sourcing, supplier risk, approvals"},{"deptId":"property","label":"Asset Management Team","label_th":"ทีมบริหารทรัพย์สิน","page":"property-asset-management","icon":"building","desc":"Track and safeguard every company-owned asset, from tools to heavy equipment.","desc_th":"ติดตามและปกป้องทรัพย์สินของบริษัททุกชิ้น ตั้งแต่เครื่องมือไปจนถึงเครื่องจักรหนัก","lead":"Mr. Watcharit Chavananand, Head of Asset Management","focus":"Registration, tracking, verification"},{"deptId":"engineering","label":"Engineering Team","label_th":"ทีมวิศวกรรม","page":"engineering-team","icon":"wrench","desc":"Turn project progress into certified, accurately measured revenue on site.","desc_th":"เปลี่ยนความคืบหน้าของโครงการให้เป็นรายได้ที่ผ่านการรับรองและวัดผลอย่างแม่นยำในไซต์งาน","lead":"Mr. Vivat Chavananand, Head of Engineering","focus":"Execution, measurement, documentation"}],"footer":"Once selected, this becomes the department you complete all three onboarding phases in — switching later means starting your checklist over from day one."}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('accounting-team', 'main', 1, 'text', null, null, 'Meet Your Supervisor', 'รู้จักหัวหน้างานของคุณ', null, null, '{"body":["Mrs. Wanpen Yamploy (Head of Accounting) and Mrs. Jirapon (Accounting Assistant) will guide new employees through onboarding."],"body_th":["คุณวันเพ็ญ ยำพลอย (หัวหน้าฝ่ายบัญชี) และคุณจิราพร (ผู้ช่วยฝ่ายบัญชี) จะเป็นผู้ดูแลการปฐมนิเทศพนักงานใหม่"],"image":null}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('accounting-team', 'main', 2, 'text', null, null, 'Department Overview', 'ภาพรวมของแผนก', null, null, '{"body":["Objective: maintaining complete, transparent, and verifiable financial records that accurately reflect the company’s operations."],"body_th":["วัตถุประสงค์: รักษาบันทึกทางการเงินที่ครบถ้วน โปร่งใส และตรวจสอบได้ ซึ่งสะท้อนการดำเนินงานของบริษัทอย่างถูกต้อง"],"bullets":["Recording transactions correctly and consistently","Ensuring compliance with tax and regulatory requirements","Maintaining audit readiness at all times","Enforcing documentation discipline within ERP systems","Supporting financial reporting integrity"],"bullets_th":["บันทึกรายการอย่างถูกต้องและสม่ำเสมอ","รับรองการปฏิบัติตามข้อกำหนดด้านภาษีและกฎระเบียบ","รักษาความพร้อมสำหรับการตรวจสอบตลอดเวลา","บังคับใช้วินัยด้านเอกสารภายในระบบ ERP","สนับสนุนความถูกต้องของการรายงานทางการเงิน"],"footer":"Accuracy is protection. Documentation is control.","footer_th":"ความถูกต้องคือการปกป้อง เอกสารคือการควบคุม"}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('accounting-team', 'main', 3, 'text', null, null, 'Workflow Within the Mango Anywhere ERP System', 'กระบวนการทำงานภายในระบบ Mango Anywhere ERP', null, null, '{"body":["Operations use the Mango Anywhere ERP system, which integrates project operations, procurement, asset management, and financial reporting through AP, AR, and GL modules. Operational departments initiate transactions; Accounting verifies, documents, and records them for General Ledger consolidation."],"body_th":["การดำเนินงานใช้ระบบ Mango Anywhere ERP ซึ่งผสานรวมการดำเนินโครงการ การจัดซื้อ การบริหารทรัพย์สิน และการรายงานทางการเงินผ่านโมดูล AP, AR และ GL แผนกปฏิบัติการเป็นผู้เริ่มรายการ ฝ่ายบัญชีจะตรวจสอบ บันทึกเอกสาร และรวบรวมเข้าบัญชีแยกประเภททั่วไป"],"image":{"imageKey":"erpFlowchart","alt":"Mango Anywhere ERP system flow diagram","className":"content-image erp-flow-photo"}}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('accounting-team', 'main', 4, 'phaselinks', null, null, 'Onboarding Phases', 'ช่วงเวลาการปฐมนิเทศ', null, null, '{"phases":[{"label":"ACCOUNTING – DAY 1–30","label_th":"บัญชี – วันที่ 1–30","page":"accounting-day-1-30"},{"label":"ACCOUNTING – DAY 31–60","label_th":"บัญชี – วันที่ 31–60","page":"accounting-day-31-60"},{"label":"ACCOUNTING – DAY 61–90","label_th":"บัญชี – วันที่ 61–90","page":"accounting-day-61-90"}]}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('finance-team', 'main', 1, 'text', null, null, 'Meet Your Supervisor', 'รู้จักหัวหน้างานของคุณ', null, null, '{"body":["Mr. Vivich Chavananand (Head of Finance) and Mrs. Sirirat (Senior Finance Officer) will guide you through the onboarding process and help you understand the systems, responsibilities, and standards of the Finance Department."],"body_th":["คุณวิวิชญ์ ชวนะนันท์ (หัวหน้าฝ่ายการเงิน) และคุณศิริรัตน์ (เจ้าหน้าที่การเงินอาวุโส) จะดูแลกระบวนการปฐมนิเทศและช่วยให้คุณเข้าใจระบบ หน้าที่ความรับผิดชอบ และมาตรฐานของฝ่ายการเงิน"],"image":null}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('finance-team', 'main', 2, 'text', null, null, 'Department Overview', 'ภาพรวมของแผนก', null, null, '{"body":["The Finance Department safeguards the company’s liquidity, financial stability, and long-term sustainability.","Primary objective: ensuring controlled cashflow, responsible debt management, and early identification of funding gaps before operational risks emerge.","Finance safeguards liquidity through:"],"body_th":["ฝ่ายการเงินทำหน้าที่ปกป้องสภาพคล่อง เสถียรภาพทางการเงิน และความยั่งยืนในระยะยาวของบริษัท","วัตถุประสงค์หลัก: รักษากระแสเงินสดให้อยู่ในการควบคุม บริหารหนี้สินอย่างมีความรับผิดชอบ และระบุช่องว่างทางการเงินตั้งแต่เนิ่นๆ ก่อนที่ความเสี่ยงด้านปฏิบัติการจะเกิดขึ้น","ฝ่ายการเงินปกป้องสภาพคล่องผ่าน:"],"bullets":["Monitoring cash inflows and outflows","Forecasting short- and medium-term funding requirements","Managing banking facilities and financing instruments","Evaluating debt servicing capacity","Protecting the company from liquidity exposure"],"bullets_th":["ติดตามกระแสเงินสดเข้าและออก","พยากรณ์ความต้องการเงินทุนระยะสั้นและระยะกลาง","บริหารวงเงินธนาคารและเครื่องมือทางการเงิน","ประเมินความสามารถในการชำระหนี้","ปกป้องบริษัทจากความเสี่ยงด้านสภาพคล่อง"],"footer":"Finance protects the liquidity that makes profitability sustainable.","footer_th":"ฝ่ายการเงินปกป้องสภาพคล่องที่ทำให้ความสามารถในการทำกำไรยั่งยืน"}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('finance-team', 'main', 3, 'text', null, null, 'Workflow Within the Mango Anywhere ERP System', 'กระบวนการทำงานภายในระบบ Mango Anywhere ERP', null, null, '{"body":["The Finance Department operates within the Mango Anywhere Enterprise Resource Planning (ERP) system, utilizing modules FIN, AP, and PM to manage resources, funding structure, and cash flow. The department monitors transactions across operational areas to maintain financial stability and enable strategic decision-making."],"body_th":["ฝ่ายการเงินดำเนินงานภายในระบบ Mango Anywhere ERP โดยใช้โมดูล FIN, AP และ PM ในการบริหารทรัพยากร โครงสร้างเงินทุน และกระแสเงินสด แผนกนี้ติดตามรายการต่างๆ ในทุกพื้นที่ปฏิบัติการเพื่อรักษาเสถียรภาพทางการเงินและสนับสนุนการตัดสินใจเชิงกลยุทธ์"],"image":{"imageKey":"erpFlowchart","alt":"Mango Anywhere ERP system flow diagram","className":"content-image erp-flow-photo"}}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('finance-team', 'main', 4, 'phaselinks', null, null, 'Onboarding Phases', 'ช่วงเวลาการปฐมนิเทศ', null, null, '{"phases":[{"label":"FINANCE – Day 1–30","label_th":"การเงิน – วันที่ 1–30","page":"finance-day-1-30"},{"label":"FINANCE – Day 31–60","label_th":"การเงิน – วันที่ 31–60","page":"finance-day-31-60"},{"label":"FINANCE – Day 61–90","label_th":"การเงิน – วันที่ 61–90","page":"finance-day-61-90"}]}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('procurement-team', 'main', 1, 'text', null, null, 'Meet Your Supervisor', 'รู้จักหัวหน้างานของคุณ', null, null, '{"body":["Mrs. Thongthip Chavananand (Head of Procurement) and Mrs. Anongrak (Senior Procurement Officer) guide onboarding."],"body_th":["คุณธงทิพย์ ชวนะนันท์ (หัวหน้าฝ่ายจัดซื้อ) และคุณอนงค์รักษ์ (เจ้าหน้าที่จัดซื้ออาวุโส) เป็นผู้ดูแลการปฐมนิเทศ"],"image":null}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('procurement-team', 'main', 2, 'text', null, null, 'Department Overview', 'ภาพรวมของแผนก', null, null, '{"body":["The procurement function protects the company’s cost structure, liquidity timing, and supply reliability. Objective: ensure that all purchasing decisions align with project requirements, financial capacity, and governance standards."],"body_th":["หน้าที่จัดซื้อทำหน้าที่ปกป้องโครงสร้างต้นทุน จังหวะเวลาของสภาพคล่อง และความน่าเชื่อถือของการจัดหา วัตถุประสงค์: รับรองว่าการตัดสินใจจัดซื้อทุกครั้งสอดคล้องกับความต้องการของโครงการ ศักยภาพทางการเงิน และมาตรฐานธรรมาภิบาล"],"bullets":["Secure materials and services at optimal commercial terms","Prevent cost escalation and over-purchasing","Align delivery schedules with project timelines","Evaluate supplier risk exposure","Enforce structured approval workflows"],"bullets_th":["จัดหาวัสดุและบริการภายใต้เงื่อนไขทางการค้าที่เหมาะสมที่สุด","ป้องกันต้นทุนที่เพิ่มขึ้นเกินควรและการจัดซื้อเกินความจำเป็น","จัดตารางการส่งมอบให้สอดคล้องกับกำหนดการของโครงการ","ประเมินความเสี่ยงจากผู้ขาย","บังคับใช้กระบวนการอนุมัติที่มีโครงสร้างชัดเจน"],"footer":"Procurement decisions directly affect project margin and cashflow stability. Cost control is not optional — it is structural protection.","footer_th":"การตัดสินใจด้านจัดซื้อส่งผลโดยตรงต่อกำไรของโครงการและเสถียรภาพกระแสเงินสด การควบคุมต้นทุนไม่ใช่ทางเลือก แต่เป็นการปกป้องเชิงโครงสร้าง"}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('procurement-team', 'main', 3, 'text', null, null, 'Workflow Within the Mango Anywhere ERP System', 'กระบวนการทำงานภายในระบบ Mango Anywhere ERP', null, null, '{"body":["Procurement operates through the Mango Anywhere ERP system, managing purchasing activities via modules: PO, PR, and IC. Requirements flow from Engineering and Project teams through the system as purchase requests and orders."],"body_th":["ฝ่ายจัดซื้อดำเนินงานผ่านระบบ Mango Anywhere ERP โดยบริหารกิจกรรมการจัดซื้อผ่านโมดูล PO, PR และ IC ความต้องการจากทีมวิศวกรรมและทีมโครงการจะไหลผ่านระบบในรูปแบบใบขอซื้อและใบสั่งซื้อ"],"image":{"imageKey":"erpFlowchart","alt":"Mango Anywhere ERP system flow diagram","className":"content-image erp-flow-photo"}}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('procurement-team', 'main', 4, 'phaselinks', null, null, 'Onboarding Phases', 'ช่วงเวลาการปฐมนิเทศ', null, null, '{"phases":[{"label":"PROCUREMENT – DAY 1–30","label_th":"จัดซื้อ – วันที่ 1–30","page":"procurement-day-1-30"},{"label":"PROCUREMENT – DAY 31–60","label_th":"จัดซื้อ – วันที่ 31–60","page":"procurement-day-31-60"},{"label":"PROCUREMENT – DAY 61–90","label_th":"จัดซื้อ – วันที่ 61–90","page":"procurement-day-61-90"}]}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('property-asset-management', 'main', 1, 'text', null, null, 'Meet Your Supervisor', 'รู้จักหัวหน้างานของคุณ', null, null, '{"body":["Mr. Watcharit Chavananand (Head of Asset Management) and Mr. Wichit (Head of Vehicles & Machinery) lead onboarding."],"image":null}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('property-asset-management', 'main', 2, 'text', null, null, 'Department Overview', 'ภาพรวมของแผนก', null, null, '{"body":["Core function: protecting company-owned assets, inventory integrity, and operational traceability. Objective: ensure that all assets are properly registered, documented, traceable, and physically verified at all times."],"body_th":["หน้าที่หลัก: ปกป้องทรัพย์สินของบริษัท ความถูกต้องของสินค้าคงคลัง และความสามารถในการตรวจสอบย้อนกลับ วัตถุประสงค์: รับรองว่าทรัพย์สินทั้งหมดได้รับการขึ้นทะเบียน จัดทำเอกสาร ตรวจสอบย้อนกลับได้ และตรวจนับจริงอยู่เสมอ"],"bullets":["Accurate asset registration and tagging","Warehouse control and movement tracking","Periodic physical verification","Prevention of loss, misuse, or misstatement","Supporting financial reporting through asset accuracy"],"bullets_th":["การขึ้นทะเบียนและติดป้ายทรัพย์สินอย่างถูกต้อง","การควบคุมคลังสินค้าและติดตามการเคลื่อนย้าย","การตรวจนับทรัพย์สินจริงตามรอบเวลา","การป้องกันการสูญหาย การใช้งานผิดวัตถุประสงค์ หรือการรายงานที่ผิดพลาด","สนับสนุนการรายงานทางการเงินผ่านความถูกต้องของข้อมูลทรัพย์สิน"],"footer":"Control preserves value. Uncontrolled assets create financial and governance exposure.","footer_th":"การควบคุมช่วยรักษามูลค่า ทรัพย์สินที่ขาดการควบคุมก่อให้เกิดความเสี่ยงทางการเงินและธรรมาภิบาล"}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('property-asset-management', 'main', 3, 'text', null, null, 'Workflow Within the Mango Anywhere ERP System', 'กระบวนการทำงานภายในระบบ Mango Anywhere ERP', null, null, '{"body":["Operates within the Mango Anywhere ERP system, managing asset tracking, utilization, and lifecycle across project sites and operational facilities through FA and IC modules. The system monitors machinery, equipment, materials, and facilities to ensure proper allocation, maintenance, and financial accountability, integrating with procurement, engineering, and accounting processes."],"body_th":["ดำเนินงานภายในระบบ Mango Anywhere ERP โดยบริหารการติดตาม การใช้งาน และวงจรชีวิตของทรัพย์สินในพื้นที่โครงการและสถานที่ปฏิบัติงานผ่านโมดูล FA และ IC ระบบนี้ติดตามเครื่องจักร อุปกรณ์ วัสดุ และสถานที่ เพื่อให้มั่นใจถึงการจัดสรร การบำรุงรักษา และความรับผิดชอบทางการเงินที่เหมาะสม โดยเชื่อมโยงกับกระบวนการจัดซื้อ วิศวกรรม และบัญชี"],"image":{"imageKey":"erpFlowchart","alt":"Mango Anywhere ERP system flow diagram","className":"content-image erp-flow-photo"}}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('property-asset-management', 'main', 4, 'phaselinks', null, null, 'Onboarding Phases', 'ช่วงเวลาการปฐมนิเทศ', null, null, '{"phases":[{"label":"PROPERTY – DAY 1–30","label_th":"บริหารทรัพย์สิน – วันที่ 1–30","page":"property-day-1-30"},{"label":"PROPERTY – DAY 31–60","label_th":"บริหารทรัพย์สิน – วันที่ 31–60","page":"property-day-31-60"},{"label":"PROPERTY – DAY 61–90","label_th":"บริหารทรัพย์สิน – วันที่ 61–90","page":"property-day-61-90"}]}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('engineering-team', 'main', 1, 'text', null, null, 'Meet Your Supervisor', 'รู้จักหัวหน้างานของคุณ', null, null, '{"body":["Mr. Vivat Chavananand (Head of Engineering) and Mrs. Romanee Karunchadit (Senior Engineer Officer) guide onboarding."],"body_th":["คุณวิวัฒน์ ชวนะนันท์ (หัวหน้าฝ่ายวิศวกรรม) และคุณโรมณี การัณยชาติ (เจ้าหน้าที่วิศวกรอาวุโส) เป็นผู้ดูแลการปฐมนิเทศ"],"image":null}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('engineering-team', 'main', 2, 'text', null, null, 'Department Overview', 'ภาพรวมของแผนก', null, null, '{"body":["Mission: revenue realization through accurate measurement, controlled execution, and disciplined documentation. Engineering must ensure project progress converts to certified revenue while maintaining cost efficiency and contractual compliance through:"],"body_th":["พันธกิจ: การรับรู้รายได้ผ่านการวัดผลที่แม่นยำ การปฏิบัติงานที่ควบคุมได้ และวินัยด้านเอกสาร ฝ่ายวิศวกรรมต้องรับรองว่าความคืบหน้าของโครงการแปลงเป็นรายได้ที่ได้รับการรับรอง พร้อมทั้งรักษาประสิทธิภาพด้านต้นทุนและการปฏิบัติตามสัญญาผ่าน:"],"bullets":["Executing work per specifications and approved drawings","Maintaining accurate quantity measurement","Controlling material and labor efficiency","Preventing schedule delays","Preparing documentation supporting progress claims"],"bullets_th":["ดำเนินงานตามข้อกำหนดและแบบที่ได้รับอนุมัติ","รักษาความแม่นยำในการวัดปริมาณงาน","ควบคุมประสิทธิภาพการใช้วัสดุและแรงงาน","ป้องกันความล่าช้าของกำหนดการ","จัดเตรียมเอกสารสนับสนุนการเบิกจ่ายตามความคืบหน้า"],"footer":"Execution accuracy safeguards revenue.","footer_th":"ความแม่นยำในการปฏิบัติงานคือการปกป้องรายได้"}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('engineering-team', 'main', 3, 'text', null, null, 'Workflow Within the Mango Anywhere ERP System', 'กระบวนการทำงานภายในระบบ Mango Anywhere ERP', null, null, '{"body":["The Mango Anywhere ERP System integrates project planning, resource allocation, procurement, and financial management. Engineering initiates operational activities through Business Development (BD) and Project Management (PM) modules that connect with other departments."],"body_th":["ระบบ Mango Anywhere ERP ผสานรวมการวางแผนโครงการ การจัดสรรทรัพยากร การจัดซื้อ และการบริหารการเงิน ฝ่ายวิศวกรรมเริ่มกิจกรรมปฏิบัติการผ่านโมดูลพัฒนาธุรกิจ (BD) และบริหารโครงการ (PM) ซึ่งเชื่อมโยงกับแผนกอื่นๆ"],"image":{"imageKey":"erpFlowchart","alt":"Mango Anywhere ERP system flow diagram","className":"content-image erp-flow-photo"}}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('engineering-team', 'main', 4, 'phaselinks', null, null, 'Onboarding Phases', 'ช่วงเวลาการปฐมนิเทศ', null, null, '{"phases":[{"label":"ENGINEERING – DAY 1–30","label_th":"วิศวกรรม – วันที่ 1–30","page":"engineering-day-1-30"},{"label":"ENGINEERING – DAY 31–60","label_th":"วิศวกรรม – วันที่ 31–60","page":"engineering-day-31-60"},{"label":"ENGINEERING – DAY 61–90","label_th":"วิศวกรรม – วันที่ 61–90","page":"engineering-day-61-90"}]}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('meet-our-team', 'main', 1, 'text', null, 'light', 'Life at Vichitbhan Construction', null, null, null, '{"body":["Beyond the job site and the ledgers, VCB is a team that shows up for each other — company parties, seasonal gatherings, and the everyday moments that make a construction company feel like more than a construction company.","These are some of those moments."]}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('meet-our-team', 'main', 2, 'trackrecord', null, null, 'New Year Party 2019', null, 'Costumes, awards, and a company-wide celebration to close out the year.', null, '{"slides":[{"image":{"imageKey":"meetTeamNyp2019Award"},"caption":"New Year Party 2019"},{"image":{"imageKey":"meetTeamNypAwardStage"},"caption":"Best Dressed Award"},{"image":{"imageKey":"meetTeamPartyGroup1"},"caption":"Company Costume Party"}]}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('meet-our-team', 'main', 3, 'trackrecord', null, null, 'Company Celebration', null, 'More moments from company gatherings over the years.', null, '{"slides":[{"image":{"imageKey":"meetTeamPartyCandid1"},"caption":"Company Celebration"},{"image":{"imageKey":"meetTeamPartyCandid2"},"caption":"Company Celebration"},{"image":{"imageKey":"meetTeamPartyCandid3"},"caption":"Company Celebration"},{"image":{"imageKey":"meetTeamPartyCandid4"},"caption":"Company Celebration"}]}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('meet-our-team', 'main', 4, 'trackrecord', null, null, 'Christmas Gathering', null, 'Seasonal get-togethers with the wider VCB team.', null, '{"slides":[{"image":{"imageKey":"meetTeamChristmas2023a"},"caption":"Christmas Gathering 2023"},{"image":{"imageKey":"meetTeamChristmas2023b"},"caption":"Christmas Gathering 2023"},{"image":{"imageKey":"meetTeamChristmasGroup"},"caption":"Christmas Gathering"}]}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('life-on-site', 'main', 1, 'text', null, null, null, null, null, null, '{"body":["Site operations are carried out in a structured and controlled environment, with a focus on safety, coordination, and adherence to defined work processes."],"body_th":["การปฏิบัติงานในไซต์ดำเนินไปในสภาพแวดล้อมที่มีโครงสร้างและการควบคุม โดยเน้นความปลอดภัย การประสานงาน และการปฏิบัติตามขั้นตอนการทำงานที่กำหนดไว้"]}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('life-on-site', 'main', 2, 'gallery', null, null, 'Safety Talk', 'การบรรยายความปลอดภัย', null, null, '{"body":"Each workday begins with a safety briefing to highlight potential risks, review ongoing activities, and reinforce site safety requirements. This ensures all personnel are aware of current site conditions, hazards, and control measures before work begins. Safety talks also provide an opportunity to address recent incidents, clarify procedures, and maintain a high level of safety awareness.","body_th":"ทุกวันทำงานเริ่มต้นด้วยการบรรยายความปลอดภัยเพื่อชี้ให้เห็นความเสี่ยงที่อาจเกิดขึ้น ทบทวนกิจกรรมที่กำลังดำเนินอยู่ และย้ำข้อกำหนดด้านความปลอดภัยของไซต์งาน สิ่งนี้ช่วยให้บุคลากรทุกคนทราบสภาพพื้นที่ อันตราย และมาตรการควบคุมก่อนเริ่มงาน การบรรยายความปลอดภัยยังเป็นโอกาสในการพูดคุยเกี่ยวกับเหตุการณ์ที่เกิดขึ้นล่าสุด ชี้แจงขั้นตอนการทำงาน และรักษาความตระหนักด้านความปลอดภัยในระดับสูง","images":[{"imageKey":"losSafetyReal1"},{"imageKey":"losSafetyReal2"}]}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('life-on-site', 'main', 3, 'gallery', null, null, 'Tool Box Talk', 'การบรรยายก่อนเริ่มงาน (Tool Box Talk)', null, null, '{"body":"Toolbox talks are conducted regularly to review specific tasks and operational details relevant to the work being carried out. These sessions focus on correct methods, equipment usage, and coordination between teams. They ensure that all personnel understand their responsibilities and any task-specific risks before execution.","body_th":"การบรรยายก่อนเริ่มงานจัดขึ้นเป็นประจำเพื่อทบทวนงานเฉพาะและรายละเอียดการปฏิบัติงานที่เกี่ยวข้อง โดยเน้นวิธีการที่ถูกต้อง การใช้งานอุปกรณ์ และการประสานงานระหว่างทีม เพื่อให้มั่นใจว่าบุคลากรทุกคนเข้าใจหน้าที่ของตนและความเสี่ยงเฉพาะของงานก่อนลงมือปฏิบัติ","images":[{"imageKey":"losToolboxReal1"},{"imageKey":"losTeamWorkReal"}]}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('life-on-site', 'main', 4, 'gallery', null, null, 'Site Training', 'การฝึกอบรมหน้างาน', null, null, '{"body":"On-site training is provided to ensure personnel are equipped with the necessary knowledge and skills to perform their duties effectively. This includes training on equipment, procedures, and safety practices. Continuous training helps maintain consistency in work quality and ensures compliance with company standards and regulatory requirements.","body_th":"การฝึกอบรมหน้างานจัดขึ้นเพื่อให้บุคลากรมีความรู้และทักษะที่จำเป็นในการปฏิบัติหน้าที่อย่างมีประสิทธิภาพ ครอบคลุมการฝึกอบรมด้านอุปกรณ์ ขั้นตอนการทำงาน และแนวปฏิบัติด้านความปลอดภัย การฝึกอบรมอย่างต่อเนื่องช่วยรักษาความสม่ำเสมอของคุณภาพงานและรับรองการปฏิบัติตามมาตรฐานบริษัทและข้อกำหนดกฎระเบียบ","images":[{"imageKey":"losTrainingReal1"},{"imageKey":"losTrainingReal2"}]}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('life-on-site', 'main', 5, 'gallery', null, null, 'House Keeping', 'การดูแลความเป็นระเบียบเรียบร้อย', null, null, '{"body":"Housekeeping is maintained throughout the site to ensure a clean, organized, and safe working environment. Proper storage of materials, clear access routes, and regular removal of waste help reduce hazards and improve operational efficiency. Good housekeeping practices are essential to minimizing risks and maintaining site discipline.","body_th":"มีการดูแลความเป็นระเบียบเรียบร้อยทั่วทั้งไซต์งานเพื่อให้สภาพแวดล้อมการทำงานสะอาด เป็นระเบียบ และปลอดภัย การจัดเก็บวัสดุอย่างเหมาะสม เส้นทางเข้าออกที่ชัดเจน และการกำจัดขยะอย่างสม่ำเสมอ ช่วยลดอันตรายและเพิ่มประสิทธิภาพการปฏิบัติงาน แนวปฏิบัติด้านความเป็นระเบียบที่ดีมีความสำคัญต่อการลดความเสี่ยงและรักษาวินัยในไซต์งาน","images":[{"imageKey":"losHousekeepingReal1"},{"imageKey":"losHousekeepingReal2"}]}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('life-on-site', 'main', 6, 'gallery', null, null, 'Work in Process', 'งานระหว่างดำเนินการ', null, null, '{"body":"All work activities are carried out in accordance with established procedures and project plans. Defined processes ensure consistency in execution, proper documentation, and alignment with cost and schedule requirements. Adherence to these processes supports quality control, accountability, and efficient resource utilization.","body_th":"กิจกรรมการทำงานทั้งหมดดำเนินไปตามขั้นตอนที่กำหนดไว้และแผนโครงการ กระบวนการที่ชัดเจนช่วยให้การปฏิบัติงานมีความสม่ำเสมอ มีเอกสารที่ถูกต้อง และสอดคล้องกับข้อกำหนดด้านต้นทุนและกำหนดเวลา การปฏิบัติตามกระบวนการเหล่านี้สนับสนุนการควบคุมคุณภาพ ความรับผิดชอบ และการใช้ทรัพยากรอย่างมีประสิทธิภาพ","images":[{"imageKey":"losWorkInProcessReal1"},{"imageKey":"losWorkInProcessReal2"}]}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('life-on-site', 'main', 7, 'gallery', null, null, 'Site Facilities', null, null, null, '{"images":[{"imageKey":"losNavigationLockReal","caption":"Navigation Lock","caption_th":"ประตูเรือสัญจร"},{"imageKey":"losPowerHouseReal","caption":"Power House Unit","caption_th":"อาคารโรงไฟฟ้า"},{"imageKey":"losSpillway","caption":"Spillway","caption_th":"ทางระบายน้ำล้น"}]}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('life-on-site', 'main', 8, 'gallery', null, null, 'Team Work', 'การทำงานเป็นทีม', null, null, '{"body":"Site operations require coordination across multiple teams. Collaboration is at the heart of our success. We rely on each other’s strengths, communicate openly, and celebrate the achievements we build together.","body_th":"การปฏิบัติงานในไซต์ต้องอาศัยการประสานงานระหว่างหลายทีม การร่วมมือกันคือหัวใจของความสำเร็จของเรา เราพึ่งพาจุดแข็งของกันและกัน สื่อสารกันอย่างเปิดเผย และร่วมเฉลิมฉลองความสำเร็จที่เราสร้างขึ้นด้วยกัน","images":[{"imageKey":"losToolboxReal2"}]}'::jsonb);
insert into ob_sections (page_key, variant, sort_order, type, section_id, band, heading, heading_th, subheading, subheading_th, data) values ('completion', 'main', 1, 'featuregrid', 'completion-section', 'completion', null, null, null, null, '{"features":[{"title":"Meet Our Team","title_th":"รู้จักทีมของเรา","body":"Explore the infrastructure works that define our execution standards. Each project reflects coordination, discipline, and long-term durability.","body_th":"สำรวจผลงานโครงสร้างพื้นฐานที่สะท้อนมาตรฐานการทำงานของเรา แต่ละโครงการแสดงถึงการประสานงาน วินัย และความคงทนในระยะยาว","image":{"imageKey":"meetTeamNyp2019Award","alt":"Meet Our Team","className":"content-image"},"link":{"label":"Learn more","label_th":"เรียนรู้เพิ่มเติม","page":"meet-our-team"}},{"title":"Check Out Life on Site","title_th":"ชมชีวิตในไซต์งาน","body":"From early morning briefings to milestone handovers, our teams operate in dynamic environments where teamwork and structure drive results.","body_th":"ตั้งแต่การประชุมสรุปงานยามเช้าไปจนถึงการส่งมอบงานตามเป้าหมาย ทีมงานของเราทำงานในสภาพแวดล้อมที่เปลี่ยนแปลงตลอดเวลา โดยอาศัยการทำงานเป็นทีมและระบบที่ชัดเจนในการขับเคลื่อนผลลัพธ์","image":{"imageKey":"losToolboxReal","alt":"Life on Site","className":"content-image"},"link":{"label":"Learn more","label_th":"เรียนรู้เพิ่มเติม","page":"life-on-site"}}],"externalCta":{"label":"Return to VCB Portal","label_th":"กลับสู่พอร์ทัล VCB","url":"https://script.google.com/a/macros/vcb-con.com/s/AKfycbxqIk8Qql3XWXIWn_p0f0FSd04i-FcWZjoXgRErlU5bTXUkpujbQ4ZN4mWco6HEQFUB/exec"}}'::jsonb);
